bash_cmds:
mkdir -p public/models && H=assets/helmet.glb; node-assets optimize $H -o public/models/helmet.glb --texture-format jpeg --geometry none --texture-quality 55 --texture-data-quality 80 2>&1 | tail -3; node-assets inspect public/models/helmet.glb --against $H 2>&1 | grep -v -e '^inspect:' -e '^note'; node -e '
const fs=require("fs");const b=fs.readFileSync("public/models/helmet.glb");
console.log("magic",b.toString("ascii",0,4),"version",b.readUInt32LE(4),"length",b.readUInt32LE(8),"actual",b.length);
const jl=b.readUInt32LE(12);const j=JSON.parse(b.toString("utf8",20,20+jl));
console.log("extensionsUsed",j.extensionsUsed,"extensionsRequired",j.extensionsRequired);
console.log("images",(j.images||[]).map(i=>i.mimeType+" "+(i.uri?"uri":"bufferView")));
console.log("textures ext", JSON.stringify((j.textures||[]).map(t=>t.extensions||null)).slice(0,200));
'

node-assets optimize assets/helmet.glb -o public/models/helmet.glb --force --texture-format jpeg --geometry none --texture-quality 55 --texture-data-quality 80 2>&1 | tail -3; node-assets inspect public/models/helmet.glb --against assets/helmet.glb 2>&1 | grep -v -e '^inspect:' -e '^note'; node -e '
const fs=require("fs");const b=fs.readFileSync("public/models/helmet.glb");
const jl=b.readUInt32LE(12);const j=JSON.parse(b.toString("utf8",20,20+jl));
console.log("magic",b.toString("ascii",0,4),"len ok",b.readUInt32LE(8)===b.length,"extensionsUsed",j.extensionsUsed,"extensionsRequired",j.extensionsRequired);'
